  // Helper Menghitung Jendela Kasbon (H+10 setelah gajian s.d. H-10 sebelum gajian)
  const getKasbonWindowInfo = (paydayDate: number, currentDateNum: number = 18): {
    isOpen: boolean;
    windowStartDay: number;
    windowEndDay: number;
    daysRemaining: number;
    description: string;
    statusBadge: string;
    badgeColor: string;
  } => {
    let startDay = (paydayDate + 10) > 30 ? (paydayDate + 10) - 30 : paydayDate + 10;
    let endDay = paydayDate - 10;
    if (endDay <= 0) endDay += 30;

    let isOpen = false;
    if (startDay <= endDay) {
      isOpen = currentDateNum >= startDay && currentDateNum <= endDay;
    } else {
      isOpen = currentDateNum >= startDay || currentDateNum <= endDay;
    }

    const remaining = isOpen ? Math.max(0, endDay - currentDateNum) : 0;
    return {
      isOpen,
      windowStartDay: startDay,
      windowEndDay: endDay,
      daysRemaining: remaining,
      description: isOpen
        ? `Jendela kasbon aktif (Tgl ${startDay} s.d. ${endDay}). Tersisa ${remaining} hari lagi sebelum cut-off.`
        : `Jendela kasbon tertutup. Pengajuan hanya dibuka tgl ${startDay} s.d. ${endDay} (H+10 setelah gajian & H-10 sebelum gajian).`,
      statusBadge: isOpen ? '✓ JENDELA KASBON TERBUKA' : '🔒 JENDELA KASBON TERTUTUP',
      badgeColor: isOpen
        ? 'bg-emerald-50 text-emerald-800 border-emerald-300'
        : 'bg-rose-50 text-rose-800 border-rose-300',
    };
  };

  // Helper Menghitung Jadwal Termin Pencairan Kasbon Harian (Maks Rp 500.000 / hari / outlet)
  const calculateKasbonDisbursement = (amount: number, maxDaily: number = 500000): {
    termsCount: number;
    terms: { termNumber: number; dayLabel: string; amount: number; note: string }[];
  } => {
    if (amount <= maxDaily) {
      return {
        termsCount: 1,
        terms: [
          {
            termNumber: 1,
            dayLabel: 'Hari Ini (Saat Approval)',
            amount: amount,
            note: 'Pencairan penuh dari kas operasional outlet',
          },
        ],
      };
    }

    const terms: { termNumber: number; dayLabel: string; amount: number; note: string }[] = [];
    let remaining = amount;
    let day = 1;

    while (remaining > 0) {
      const chunk = Math.min(remaining, maxDaily);
      const dayLabel = day === 1 ? 'Hari Ke-1 (Hari Ini)' : day === 2 ? 'Hari Ke-2 (Besok)' : `Hari Ke-${day}`;
      terms.push({
        termNumber: day,
        dayLabel,
        amount: chunk,
        note: `Pencairan bertahap kasbon harian (Maks Rp ${maxDaily.toLocaleString('id-ID')}/hari)`,
      });
      remaining -= chunk;
      day++;
    }

    return {
      termsCount: terms.length,
      terms,
    };
  };

