                                      setGenCustomClause(EDARAN_TEMPLATES.SE_LIBUR_OPERASIONAL);
                                      setGenAnnouncementSubject('Himbauan Operasional & Penyesuaian Jadwal Libur Restoran (Peak Season)');
                                      setGenNewOutlet('Semua Cabang Restoran Barokah Grup');
                                      setGenSignatoryName('Arif Gunawan Panggabean');
