                      const timeStampStr = `${nowDate}, ${nowTime}`;
                      const photoSrc =
                        attendanceCameraModal.staffRole.toLowerCase().includes('koki') ||
                        attendanceCameraModal.staffRole.toLowerCase().includes('cook')
